namespace Astera {
static class Program {
    [STAThread] static int Main(string[] args){
        if(args.Length==2&&args[0]=="--layout-audit")return LibraryForm.AuditLayout(args[1]);
        if(args.Length==2&&args[0]=="--self-test")return NetworkSelfTest.Run(args[1]);
        if(args.Length==2&&args[0]=="--engine-self-test")return SelfTest.Run(args[1]);
        if(args.Length==4&&args[0]=="--audit-channel")return HostedAudit.Run(args[1],args[2],args[3]);
        if(args.Length==2&&args[0]=="--verify-feed"){try{Channel source;using(var reader=new StreamReader(Assembly.GetExecutingAssembly().GetManifestResourceStream("Astera.Channel")))source=Engine.Json.Deserialize<Channel>(reader.ReadToEnd());var feed=new UpdateClient(source.PublicKeyXml).Verify(File.ReadAllBytes(args[1]));File.WriteAllText(args[1]+".verified.json",Engine.Json.Serialize(new{Passed=true,Release=feed.Release.Name,Sequence=feed.Release.Sequence,ManagedFiles=feed.Release.Files.Count,RequiredMods=feed.RequiredMods.Count}));return 0;}catch(Exception error){File.WriteAllText(args[1]+".failure.txt",error.ToString());return 1;}}
        Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
        Application.ThreadException+=delegate(object sender,ThreadExceptionEventArgs e){AsteraDiagnostics.Report("Windows Forms event",e.Exception);};
        AppDomain.CurrentDomain.UnhandledException+=delegate(object sender,UnhandledExceptionEventArgs e){AsteraDiagnostics.Write("Unhandled process exception",e.ExceptionObject as Exception);};
        TaskScheduler.UnobservedTaskException+=delegate(object sender,UnobservedTaskExceptionEventArgs e){AsteraDiagnostics.Write("Unobserved background task",e.Exception);e.SetObserved();};
        try{var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Astera");if(args.Length==2&&args[0]=="--data-dir")root=Path.GetFullPath(args[1]);AsteraDiagnostics.Initialize(root);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Channel channel;using(var reader=new StreamReader(Assembly.GetExecutingAssembly().GetManifestResourceStream("Astera.Channel")))channel=Engine.Json.Deserialize<Channel>(reader.ReadToEnd());Application.Run(new LibraryForm(new Store(root),channel));AsteraDiagnostics.Write("Session ended",null);return 0;}catch(Exception error){AsteraDiagnostics.Report("Startup or message loop",error);return 1;}
    }
}
