        var help=new Label{Text="Astera recognises renamed profiles. “But Again” is the old folder name.\nNo profile yet? Create/import Minecraft Squared in CurseForge, then choose it here.",AutoSize=true,Margin=new Padding(0,8,0,14)};grid.Controls.Add(help,0,2);grid.SetColumnSpan(help,2);
