        chooseDash.Click+=delegate{using(var d=new OpenFileDialog{Filter="StarDash app|StarDash.exe|Windows applications|*.exe",Title="Choose StarDash.exe beside its StarDash.pck"})if(d.ShowDialog()==DialogResult.OK)stardash.Text=d.FileName;};grid.Controls.Add(chooseDash,1,4);
